	a1 := uint64(x.B0.A1[0])
	a2 := uint64(x.B1.A0[0])
	a3 := uint64(x.B1.A1[0])
	a4 := uint64(x.B2.A0[0])
	a5 := uint64(x.B2.A1[0])

