// Inverse sets z to the inverse of x in E6 and returns z
//
// if x == 0, sets and returns z = x
func (z *E6) Inverse(x *E6) *E6 {
	// Algorithm 17 from https://eprint.iacr.org/2010/354.pdf
	// step 9 is wrong in the paper it's t1-t4
	var t0, t1, t2, t3, t4, t5, t6, c0, c1, c2, d1, d2 E2
	t0.Square(&x.B0)
	t1.Square(&x.B1)
	t2.Square(&x.B2)
	t3.Mul(&x.B0, &x.B1)
	t4.Mul(&x.B0, &x.B2)
	t5.Mul(&x.B1, &x.B2)
	c0.MulByCubicNonResidue(&t5).Neg(&c0).Add(&c0, &t0)
	c1.MulByCubicNonResidue(&t2).Sub(&c1, &t3)
	c2.Sub(&t1, &t4)
	t6.Mul(&x.B0, &c0)
	d1.Mul(&x.B2, &c1)
	d2.Mul(&x.B1, &c2)
	d1.Add(&d1, &d2).MulByCubicNonResidue(&d1)
	t6.Add(&t6, &d1)
	t6.Inverse(&t6)
	z.B0.Mul(&c0, &t6)
	z.B1.Mul(&c1, &t6)
	z.B2.Mul(&c2, &t6)

	return z
}

// Exp sets z=xᵏ (mod q⁶) and returns it
func (z *E6) Exp(x E6, k *big.Int) *E6 {
	if k.IsInt64() {
		return z.ExpInt64(x, k.Int64())
	}

	e := k
	if k.Sign() == -1 {
		// negative k, we invert
		// if k < 0: xᵏ (mod q⁶) == (x⁻¹)ᵏ (mod q⁶)
		x.Inverse(&x)

		// we negate k in a temp big.Int since
		// Int.Bit(_) of k and -k is different
		e = bigIntPool.Get().(*big.Int)
		defer bigIntPool.Put(e)
		e.Neg(k)
	}

	// Iterate over the bytes of |k|, starting from the most-significant byte.
	// Skip leading zero bits of the first non-zero byte so we don't waste
	// squarings on bits above the most-significant 1.
	b := e.Bytes()
	if len(b) == 0 {
		return z.SetOne()
	}
	z.Set(&x)
	first := b[0]
	for j := bits.LeadingZeros8(first) + 1; j < 8; j++ {
		z.Square(z)
		if (first & (0b10000000 >> j)) != 0 {
			z.Mul(z, &x)
		}
	}
	for i := 1; i < len(b); i++ {
		w := b[i]
		for j := 0; j < 8; j++ {
			z.Square(z)
			if (w & (0b10000000 >> j)) != 0 {
				z.Mul(z, &x)
			}
		}
	}

	return z
}

// ExpInt64 sets z=xᵏ (mod q⁶) and returns it, where k is an int64
func (z *E6) ExpInt64(x E6, k int64) *E6 {
	if k == 0 {
		return z.SetOne()
	}

	exp := k
	if k < 0 {
		x.Inverse(&x)
		exp = -k // if k == math.MinInt64, -k overflows, but uint64(-k) is correct
	}

	z.Set(&x)
	for i := bits.Len64(uint64(exp)) - 2; i >= 0; i-- {
		z.Square(z)
		if (uint64(exp)>>uint(i))&1 != 0 {
			z.Mul(z, &x)
		}
	}
	return z
}

// Halve divides z in-place by 2.
func (z *E6) Halve() {
	z.B0.A0.Halve()
	z.B0.A1.Halve()
	z.B1.A0.Halve()
	z.B1.A1.Halve()
	z.B2.A0.Halve()
	z.B2.A1.Halve()
}

// BatchInvertE6 returns a new slice with every element in a inverted.
// It uses Montgomery batch inversion trick.
//
// if a[i] == 0, returns result[i] = a[i]
func BatchInvertE6(a []E6) []E6 {
	res := make([]E6, len(a))
	BatchInvertE6Into(res, a)
	return res
}

// BatchInvertE6Into sets res[i] to the inverse of a[i], using Montgomery batch
// inversion trick; if a[i] == 0, res[i] = 0. res and a must have the same
// length.
//
// res may be the very same slice as a (in place), but must not otherwise
// overlap it. When res and a are distinct, BatchInvertE6Into does not
// allocate: res holds the running products. In place, it needs len(a) elements
// of scratch space, which it takes from an internal pool (allocating only when
// the pool has none large enough); use BatchInvertE6IntoScratch to provide
// them.
//
// For long inputs, BatchInvertE6IntoScratch is faster even when res and a are
// distinct, since keeping the running products apart saves a pass over a.
func BatchInvertE6Into(res, a []E6) {
	if len(res) != len(a) {
		panic("BatchInvertE6Into: vectors don't have the same length")
	}
	if len(a) == 0 {
		return
	}
	if &res[0] != &a[0] {
		if batchInvertE6Overlap(res, a) {
			panic("BatchInvertE6Into: res and a overlap without being the same slice")
		}
		batchInvertE6(res, a, nil, batchInvertE6Lanes(len(a)))
		return
	}
	if uintptr(len(a))*unsafe.Sizeof(E6{}) > batchInvertE6PoolMaxBytes {
		batchInvertE6(res, a, make([]E6, len(a)), batchInvertE6Lanes(len(a)))
		return
	}
	scratch := batchInvertE6ScratchPool.Get().(*[]E6)
	if cap(*scratch) < len(a) {
		*scratch = make([]E6, len(a))
	}
	batchInvertE6(res, a, (*scratch)[:len(a)], batchInvertE6Lanes(len(a)))
	batchInvertE6ScratchPool.Put(scratch)
}

// batchInvertE6PoolMaxBytes is the size of the largest scratch buffer kept in
// batchInvertE6ScratchPool; larger ones are left to the garbage collector, so that a
// single long in-place call does not pin its scratch space.
const batchInvertE6PoolMaxBytes = 4 << 20

// batchInvertE6Overlap reports whether x and y share memory; both are non-empty.
func batchInvertE6Overlap(x, y []E6) bool {
	const size = unsafe.Sizeof(E6{})
	xs, ys := uintptr(unsafe.Pointer(&x[0])), uintptr(unsafe.Pointer(&y[0]))
	return xs < ys+uintptr(len(y))*size && ys < xs+uintptr(len(x))*size
}

// batchInvertE6ScratchPool holds the scratch space of in-place
// BatchInvertE6Into calls.
var batchInvertE6ScratchPool = sync.Pool{
	New: func() any { return new([]E6) },
}

// BatchInvertE6IntoScratch is BatchInvertE6Into with caller-provided scratch
// space, so that it never allocates, including in place (res may be the very
// same slice as a, but must not otherwise overlap it).
//
// scratch must have at least len(a) elements and must not overlap res or a;
// its content on return is unspecified.
func BatchInvertE6IntoScratch(res, a, scratch []E6) {
	if len(res) != len(a) {
		panic("BatchInvertE6IntoScratch: vectors don't have the same length")
	}
	if len(scratch) < len(a) {
		panic("BatchInvertE6IntoScratch: scratch is shorter than the input")
	}
	if len(a) == 0 {
		return
	}
	scratch = scratch[:len(a)]
	if batchInvertE6Overlap(scratch, res) || batchInvertE6Overlap(scratch, a) {
		panic("BatchInvertE6IntoScratch: scratch overlaps res or a")
	}
	if &res[0] != &a[0] && batchInvertE6Overlap(res, a) {
		panic("BatchInvertE6IntoScratch: res and a overlap without being the same slice")
	}
	batchInvertE6(res, a, scratch, batchInvertE6Lanes(len(a)))
}

const (
	// batchInvertE6MinLanes is the narrowest row of batchInvertE6Chains,
	// the block size of the vectorised VectorE6.Mul.
	batchInvertE6MinLanes = 16
	// batchInvertE6MaxLanes is the widest row of batchInvertE6Chains; it
	// sizes the stack buffers, which are zeroed on every call.
	batchInvertE6MaxLanes = 256
)

// batchInvertE6Lanes returns the number of interleaved product chains
// batchInvertE6 runs for n elements, 0 meaning the scalar path. Wider rows
// amortise the per-call cost of the vectorised VectorE6.Mul and keep more
// independent products in flight, while every chain adds to the inversion of
// the chain products; the thresholds are measured
// (BenchmarkBatchInvertE6Lanes). Without the AVX-512 kernel (arm64
// included), VectorE6.Mul is a plain loop with no per-call cost to amortise, and
// the two interleaved chains of batchInvertE6Scalar already hide the
// latency of E6.Mul: the scalar path is the fastest at every size
// (measured on Apple M4).
func batchInvertE6Lanes(n int) int {
	if !cpu.SupportAVX512 {
		return 0
	}
	switch {
	case n < 48:
		// below this, inverting the chain products costs more than the
		// chains save: the scalar path is the fastest.
		return 0
	case n >= 8192:
		return 256
	case n >= 1024:
		return 128
	case n >= 512:
		return 64
	case n >= 128:
		return 32
	default:
		return batchInvertE6MinLanes
	}
}

// batchInvertE6 is the implementation of BatchInvertE6Into: the scalar
// path (batchInvertE6Scalar) if lanes is 0, the interleaved product chains
// (batchInvertE6Chains) otherwise. len(a) must be > 0. scratch is
// either nil, and then res and a are distinct, or len(a) elements disjoint
// from res and a, and then res may be the very same slice as a.
func batchInvertE6(res, a, scratch []E6, lanes int) {
	if lanes > 0 {
		batchInvertE6Chains(res, a, scratch, lanes)
		return
	}
	prefix := res
	if &res[0] == &a[0] {
		prefix = scratch
	}
	batchInvertE6Scalar(res, a, prefix)
}

// batchInvertE6Scalar is the Montgomery batch inversion of a into res, with
// the running products in prefix. len(a) must be > 0 and len(res), len(prefix)
// >= len(a). prefix is either res, and then res and a are distinct, or
// disjoint from res and a, and then res may be the very same slice as a.
//
// It runs two interleaved chains, over the even and the odd indices, so that
// the products of one chain overlap the latency of the other's; the
// accumulators are kept out of reach of pointers so they can stay in
// registers.
func batchInvertE6Scalar(res, a, prefix []E6) {
	n := len(a)
	res, prefix = res[:n], prefix[:n]
	m := n &^ 1
	var acc0, acc1 E6
	acc0.SetOne()
	acc1.SetOne()

	for i := 0; i < m; i += 2 {
		if a[i].IsZero() {
			prefix[i].SetZero()
		} else {
			prefix[i] = acc0
			acc0.Mul(&acc0, &a[i])
		}
		if a[i+1].IsZero() {
			prefix[i+1].SetZero()
		} else {
			prefix[i+1] = acc1
			acc1.Mul(&acc1, &a[i+1])
		}
	}
	if m < n {
		if a[m].IsZero() {
			prefix[m].SetZero()
		} else {
			prefix[m] = acc0
			acc0.Mul(&acc0, &a[m])
		}
	}

	acc0, acc1 = batchInvertE6Pair(acc0, acc1)

	// a[i] is read before res[i] is written, since they may be the same.
	if m < n {
		if x := a[m]; x.IsZero() {
			res[m].SetZero()
		} else {
			res[m].Mul(&prefix[m], &acc0)
			acc0.Mul(&acc0, &x)
		}
	}
	for i := m - 2; i >= 0; i -= 2 {
		if x := a[i+1]; x.IsZero() {
			res[i+1].SetZero()
		} else {
			res[i+1].Mul(&prefix[i+1], &acc1)
			acc1.Mul(&acc1, &x)
		}
		if x := a[i]; x.IsZero() {
			res[i].SetZero()
		} else {
			res[i].Mul(&prefix[i], &acc0)
			acc0.Mul(&acc0, &x)
		}
	}
}

// batchInvertE6Pair returns the inverses of the nonzero x and y, with a
// single E6 inversion.
func batchInvertE6Pair(x, y E6) (E6, E6) {
	var inv, xInv, yInv E6
	inv.Mul(&x, &y)
	inv.Inverse(&inv)
	xInv.Mul(&inv, &y)
	yInv.Mul(&inv, &x)
	return xInv, yInv
}

// batchInvertE6Chains runs the
// Montgomery batch inversion as interleaved product chains: the elements are
// laid out in rows, one chain per column, so that the running products of a
// row are a single vectorised VectorE6.Mul. Rows are lanes wide, then
// batchInvertE6MinLanes wide for the remainder, and the last few elements form
// one more chain multiplied scalar by scalar. The chain products are then
// inverted together with a single E6 inversion. A zero element enters its
// chain as one and gets a zero running product, so that its inverse comes out
// as zero.
//
// lanes must be a multiple of batchInvertE6MinLanes, at most
// batchInvertE6MaxLanes, and len(a) must be > 0. If scratch is nil, res and a
// must be distinct and res holds the running products. Otherwise scratch holds
// them, must be disjoint from res and a and have len(a) elements, and res
// holds a with its zeros replaced by one in between the two passes, so it may
// be the very same slice as a.
func batchInvertE6Chains(res, a, scratch []E6, lanes int) {
	n := len(a)
	inRes := scratch == nil
	prefix := scratch
	if inRes {
		prefix = res
	}

	// row boundaries: [0, wide) in rows of lanes, [wide, narrow) in rows of
	// batchInvertE6MinLanes, [narrow, n) one scalar chain.
	wide := n / lanes * lanes
	narrow := wide + (n-wide)/batchInvertE6MinLanes*batchInvertE6MinLanes

	// acc[l] is the running product of chain l, acc[lanes] that of the scalar
	// chain.
	var accBuf [batchInvertE6MaxLanes + 1]E6
	acc := accBuf[:lanes+1]
	for l := range acc {
		acc[l].SetOne()
	}
	tail := &acc[lanes]
	// row holds a row of a with its zeros replaced by one.
	var rowBuf [batchInvertE6MaxLanes]E6

	// forward pass: prefix[i] is the product of the earlier elements of the
	// chain of i, or zero if a[i] is zero.
	forward := func(j, w int) {
		row := rowBuf[:w]
		if !inRes {
			row = res[j : j+w]
		}
		p := prefix[j : j+w]
		copy(p, acc[:w])
		copy(row, a[j:j+w])
		for k := range row {
			if row[k].IsZero() {
				row[k].SetOne()
				p[k].SetZero()
			}
		}
		VectorE6(acc[:w]).Mul(acc[:w], row)
	}
	for j := 0; j < wide; j += lanes {
		forward(j, lanes)
	}
	for j := wide; j < narrow; j += batchInvertE6MinLanes {
		forward(j, batchInvertE6MinLanes)
	}
	for i := narrow; i < n; i++ {
		if a[i].IsZero() {
			prefix[i].SetZero()
			if !inRes {
				res[i].SetOne()
			}
			continue
		}
		prefix[i] = *tail
		if !inRes {
			res[i] = a[i]
		}
		tail.Mul(tail, &a[i])
	}

	batchInvertE6ChainProducts(acc)

	// backward pass: the inverse of element i is the running inverse of its
	// chain times prefix[i]; the row is read before res is overwritten.
	for i := n - 1; i >= narrow; i-- {
		x := res[i]
		if inRes {
			x = a[i]
			if x.IsZero() {
				continue
			}
		}
		res[i].Mul(tail, &prefix[i])
		tail.Mul(tail, &x)
	}
	backward := func(j, w int) {
		row := rowBuf[:w]
		if inRes {
			copy(row, a[j:j+w])
			for k := range row {
				if row[k].IsZero() {
					row[k].SetOne()
				}
			}
		} else {
			copy(row, res[j:j+w])
		}
		VectorE6(res[j:j+w]).Mul(acc[:w], prefix[j:j+w])
		VectorE6(acc[:w]).Mul(acc[:w], row)
	}
	for j := narrow - batchInvertE6MinLanes; j >= wide; j -= batchInvertE6MinLanes {
		backward(j, batchInvertE6MinLanes)
	}
	for j := wide - lanes; j >= 0; j -= lanes {
		backward(j, lanes)
	}
}

// batchInvertE6ChainProducts inverts the chain products p of
// batchInvertE6Chains in place; they are all nonzero and at most
// batchInvertE6MaxLanes+1. The recursion ends since batchInvertE6Lanes
// returns 0 (the scalar path) for short inputs, and fewer lanes than elements
// otherwise.
func batchInvertE6ChainProducts(p []E6) {
	var prefix [batchInvertE6MaxLanes + 1]E6
	batchInvertE6(p, p, prefix[:len(p)], batchInvertE6Lanes(len(p)))
}

// Div divides an element in E6 by an element in E6
func (z *E6) Div(x *E6, y *E6) *E6 {
	var r E6
	r.Inverse(y).Mul(x, &r)
	return z.Set(&r)
}

// ButterflyE6 computes the butterfly operation on two E6 elements
func ButterflyE6(a, b *E6) {
	fr.Butterfly(&a.B0.A0, &b.B0.A0)
	fr.Butterfly(&a.B0.A1, &b.B0.A1)

	fr.Butterfly(&a.B1.A0, &b.B1.A0)
	fr.Butterfly(&a.B1.A1, &b.B1.A1)

	fr.Butterfly(&a.B2.A0, &b.B2.A0)
	fr.Butterfly(&a.B2.A1, &b.B2.A1)
}

// VectorE6 represents a vector of E6 elements
type VectorE6 []E6

// SetRandom sets all elements of vector to random values, returning the first error encountered, if any.
func (vector VectorE6) SetRandom() error {
	for i := range vector {
		if _, err := vector[i].SetRandom(); err != nil {
			return err
		}
	}
	return nil
}

// MustSetRandom sets all elements of vector to random values, panicking if an error is encountered.
func (vector VectorE6) MustSetRandom() {
	for i := range vector {
		vector[i].MustSetRandom()
	}
}

// Neg sets vector[i] = -a[i]. vector may be identical to a; partially overlapping slices are not supported.
func (vector VectorE6) Neg(a VectorE6) {
	if len(a) != len(vector) {
		panic("vector.Neg: vectors don't have the same length")
	}
	v := asBaseVector(vector)
	v.Neg(asBaseVector(a))
}

// ScalarAddElement sets vector[i] = a[i] + c for all i, where c is an element
// of the base field embedded in E6.
//
// vector may be identical to a, and c may point into vector; partially
// overlapping slices are not supported.
func (vector VectorE6) ScalarAddElement(a VectorE6, c *fr.Element) {
	N := len(vector)
	if len(a) != N {
		panic("vector.ScalarAddElement: vectors don't have the same length")
	}
	if N == 0 {
		return
	}
	cc := *c
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		// the lift of c only has a nonzero first coordinate: the ScalarAdd
		// kernel adds zero to the others.
		nr := N - N%blockSize
		var lift E6
		lift.B0.A0 = cc
		cTiled := tileE6Scalar(&lift)
		vectorScalarAdd_E6_avx512(&vector[0], &a[0], &cTiled[0], uint64(nr))
		vector, a = vector[nr:], a[nr:]
	}
	for i := range vector {
		vector[i].AddElement(&a[i], &cc)
	}
}

// ScalarSubElement sets vector[i] = a[i] - c for all i, where c is an element
// of the base field embedded in E6.
//
// vector may be identical to a, and c may point into vector; partially
// overlapping slices are not supported.
func (vector VectorE6) ScalarSubElement(a VectorE6, c *fr.Element) {
	var negC fr.Element
	negC.Neg(c)
	vector.ScalarAddElement(a, &negC)
}

// ScalarSubFromElement sets vector[i] = c - a[i] for all i, where c is an
// element of the base field embedded in E6.
//
// vector may be identical to a, and c may point into vector; partially
// overlapping slices are not supported.
func (vector VectorE6) ScalarSubFromElement(c *fr.Element, a VectorE6) {
	N := len(vector)
	if len(a) != N {
		panic("vector.ScalarSubFromElement: vectors don't have the same length")
	}
	if N == 0 {
		return
	}
	cc := *c
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		// the lift of c only has a nonzero first coordinate: the ScalarSubFrom
		// kernel negates the others.
		nr := N - N%blockSize
		var lift E6
		lift.B0.A0 = cc
		cTiled := tileE6Scalar(&lift)
		vectorScalarSubFrom_E6_avx512(&vector[0], &a[0], &cTiled[0], uint64(nr))
		vector, a = vector[nr:], a[nr:]
	}
	for i := range vector {
		vector[i].SubFromElement(&cc, &a[i])
	}
}

// Sum returns the sum of all elements in the vector.
func (vector VectorE6) Sum() E6 {
	var sum E6
	const blockSize = 8
	N := len(vector)
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		// lane p of the accumulator holds a partial (unreduced) sum of
		// coordinate p%6; reduce each lane mod q before folding so the fold
		// cannot overflow.
		var t [24]uint64
		vectorSum_E6_avx512(&t, &vector[0], uint64(nr))
		var c [6]uint64
		for p := range t {
			c[p%6] += t[p] % q
		}
		sum.B0.A0[0] = uint32(c[0] % q)
		sum.B0.A1[0] = uint32(c[1] % q)
		sum.B1.A0[0] = uint32(c[2] % q)
		sum.B1.A1[0] = uint32(c[3] % q)
		sum.B2.A0[0] = uint32(c[4] % q)
		sum.B2.A1[0] = uint32(c[5] % q)
		vector = vector[nr:]
	}
	for i := range vector {
		sum.Add(&sum, &vector[i])
	}
	return sum
}

// Add sets vector[i] = a[i] + b[i]. vector may be identical to a and/or b;
// partially overlapping slices are not supported.
func (vector VectorE6) Add(a, b VectorE6) {
	if len(a) != len(vector) || len(b) != len(vector) {
		panic("vector.Add: vectors don't have the same length")
	}
	v := asBaseVector(vector)
	v.Add(asBaseVector(a), asBaseVector(b))
}

// Sub sets vector[i] = a[i] - b[i]. vector may be identical to a and/or b;
// partially overlapping slices are not supported.
func (vector VectorE6) Sub(a, b VectorE6) {
	if len(a) != len(vector) || len(b) != len(vector) {
		panic("vector.Sub: vectors don't have the same length")
	}
	v := asBaseVector(vector)
	v.Sub(asBaseVector(a), asBaseVector(b))
}

// ScalarAdd sets vector[i] = a[i] + c for all i.
//
// vector may be identical to a, and c may point into vector or a; partially
// overlapping slices are not supported.
func (vector VectorE6) ScalarAdd(a VectorE6, c *E6) {
	N := len(vector)
	if len(a) != N {
		panic("vectorE6.ScalarAdd: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	cc := *c
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		cTiled := tileE6Scalar(&cc)
		vectorScalarAdd_E6_avx512(&vector[0], &a[0], &cTiled[0], uint64(nr))
		vector, a = vector[nr:], a[nr:]
	}
	for i := range vector {
		vector[i].Add(&a[i], &cc)
	}
}

// ScalarSub sets vector[i] = a[i] - c for all i.
//
// vector may be identical to a, and c may point into vector or a; partially
// overlapping slices are not supported.
func (vector VectorE6) ScalarSub(a VectorE6, c *E6) {
	if len(vector) != len(a) {
		panic("vectorE6.ScalarSub: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	var negC E6
	negC.Neg(c)
	vector.ScalarAdd(a, &negC)
}

// ScalarSubFrom sets vector[i] = c - a[i] for all i.
//
// vector may be identical to a, and c may point into vector or a; partially
// overlapping slices are not supported.
func (vector VectorE6) ScalarSubFrom(c *E6, a VectorE6) {
	N := len(vector)
	if len(a) != N {
		panic("vectorE6.ScalarSubFrom: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	cc := *c
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		cTiled := tileE6Scalar(&cc)
		vectorScalarSubFrom_E6_avx512(&vector[0], &a[0], &cTiled[0], uint64(nr))
		vector, a = vector[nr:], a[nr:]
	}
	for i := range vector {
		vector[i].Sub(&cc, &a[i])
	}
}

// AddElement sets vector[i] = a[i] + b[i] for all i, where b[i] is an element
// of the base field embedded in E6.
//
// vector may be identical to a; partially overlapping slices are not supported.
func (vector VectorE6) AddElement(a VectorE6, b fr.Vector) {
	N := len(vector)
	if len(a) != N || len(b) != N {
		panic("vectorE6.AddElement: vectors don't have the same length")
	}
	if N == 0 {
		return
	}
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		nr := N - N%blockSize
		vectorAddElement_E6_avx512(&vector[0], &a[0], &b[0], uint64(nr))
		vector, a, b = vector[nr:], a[nr:], b[nr:]
	}
	for i := range vector {
		vector[i].AddElement(&a[i], &b[i])
	}
}

// SubElement sets vector[i] = a[i] - b[i] for all i, where b[i] is an element
// of the base field embedded in E6.
//
// vector may be identical to a; partially overlapping slices are not supported.
func (vector VectorE6) SubElement(a VectorE6, b fr.Vector) {
	N := len(vector)
	if len(a) != N || len(b) != N {
		panic("vectorE6.SubElement: vectors don't have the same length")
	}
	if N == 0 {
		return
	}
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		nr := N - N%blockSize
		vectorSubElement_E6_avx512(&vector[0], &a[0], &b[0], uint64(nr))
		vector, a, b = vector[nr:], a[nr:], b[nr:]
	}
	for i := range vector {
		vector[i].SubElement(&a[i], &b[i])
	}
}

// SubFromElement sets vector[i] = a[i] - b[i] for all i, where a[i] is an
// element of the base field embedded in E6.
//
// vector may be identical to b; partially overlapping slices are not supported.
func (vector VectorE6) SubFromElement(a fr.Vector, b VectorE6) {
	N := len(vector)
	if len(a) != N || len(b) != N {
		panic("vectorE6.SubFromElement: vectors don't have the same length")
	}
	if N == 0 {
		return
	}
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		nr := N - N%blockSize
		vectorSubFromElement_E6_avx512(&vector[0], &b[0], &a[0], uint64(nr))
		vector, a, b = vector[nr:], a[nr:], b[nr:]
	}
	for i := range vector {
		vector[i].SubFromElement(&a[i], &b[i])
	}
}

// ScalarAddBase sets vector[i] = a[i] + c for all i, where a[i] is an element
// of the base field embedded in E6.
//
// c may point into vector; partially overlapping slices are not supported.
func (vector VectorE6) ScalarAddBase(a fr.Vector, c *E6) {
	if len(vector) != len(a) {
		panic("vectorE6.ScalarAddBase: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	// embedding a[i] only touches the first coordinate: the others are copies
	// of c.
	cc := *c
	const blockSize = 8
	if cpu.SupportAVX512 && len(vector) >= blockSize {
		nr := len(vector) - len(vector)%blockSize
		cTiled := tileE6Scalar(&cc)
		vectorScalarAddBase_E6_avx512(&vector[0], &a[0], &cTiled[0], uint64(nr))
		vector, a = vector[nr:], a[nr:]
	}
	for i := range vector {
		r := cc
		r.B0.A0.Add(&cc.B0.A0, &a[i])
		vector[i] = r
	}
}

// ScalarSubBase sets vector[i] = a[i] - c for all i, where a[i] is an element
// of the base field embedded in E6.
//
// c may point into vector; partially overlapping slices are not supported.
func (vector VectorE6) ScalarSubBase(a fr.Vector, c *E6) {
	if len(vector) != len(a) {
		panic("vectorE6.ScalarSubBase: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	var negC E6
	negC.Neg(c)
	vector.ScalarAddBase(a, &negC)
}

// ScalarSubFromBase sets vector[i] = c - a[i] for all i, where a[i] is an
// element of the base field embedded in E6.
//
// c may point into vector; partially overlapping slices are not supported.
func (vector VectorE6) ScalarSubFromBase(c *E6, a fr.Vector) {
	if len(vector) != len(a) {
		panic("vectorE6.ScalarSubFromBase: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	cc := *c
	const blockSize = 8
	if cpu.SupportAVX512 && len(vector) >= blockSize {
		nr := len(vector) - len(vector)%blockSize
		cTiled := tileE6Scalar(&cc)
		vectorScalarSubFromBase_E6_avx512(&vector[0], &a[0], &cTiled[0], uint64(nr))
		vector, a = vector[nr:], a[nr:]
	}
	for i := range vector {
		r := cc
		r.B0.A0.Sub(&cc.B0.A0, &a[i])
		vector[i] = r
	}
}

// Mul sets vector[i] = a[i] * b[i]. vector may alias a or b.
func (vector VectorE6) Mul(a, b VectorE6) {
	N := len(vector)
	if len(a) != N || len(b) != N {
		panic("vectorE6.Mul: vectors don't have the same length")
	}
	const blockSize = 16
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		vectorMul_E6_avx512(&vector[0], &a[0], &b[0], uint64(nr))
		vector, a, b = vector[nr:], a[nr:], b[nr:]
	}
	for i := range vector {
		vector[i].Mul(&a[i], &b[i])
	}
}

// InnerProduct returns the sum of vector[i] * a[i].
func (vector VectorE6) InnerProduct(a VectorE6) E6 {
	N := len(vector)
	if len(a) != N {
		panic("vectorE6.InnerProduct: vectors don't have the same length")
	}
	var res E6
	const blockSize = 16
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		var t [6 * 4]uint64 // accumulators, 4 per coordinate (not reduced mod q)
		vectorInnerProduct_E6_avx512(&t, &vector[0], &a[0], uint64(nr))
		var c [6]uint32
		for k := range c {
			var s uint64
			for _, v := range t[4*k : 4*k+4] {
				s += v % q
			}
			c[k] = uint32(s % q)
		}
		res.B0.A0[0], res.B0.A1[0] = c[0], c[1]
		res.B1.A0[0], res.B1.A1[0] = c[2], c[3]
		res.B2.A0[0], res.B2.A1[0] = c[4], c[5]
		vector, a = vector[nr:], a[nr:]
	}
	var t E6
	for i := range vector {
		t.Mul(&vector[i], &a[i])
		res.Add(&res, &t)
	}
	return res
}

// FoldPairs folds layer in pairs, as in one FRI folding round:
//
//	vector[j] = (layer[2j] + layer[2j+1]) / 2 + alpha · halfInvTwiddles[j] · (layer[2j] − layer[2j+1])
//
// FoldPairs halves the even part (p + q) itself, but multiplies the odd part
// (p − q) by halfInvTwiddles[j] as given: callers pass (2·x_j)⁻¹, where x_j is
// the evaluation point of the pair. Callers holding x_j⁻¹ must halve it first,
// or the odd term is off by a factor of 2.
//
// It panics unless len(layer) == 2·len(vector) and
// len(halfInvTwiddles) == len(vector). vector may be layer[:len(vector)]
// (folding in place); alpha may point into vector or layer. Other overlaps are
// not supported.
func (vector VectorE6) FoldPairs(layer VectorE6, halfInvTwiddles fr.Vector, alpha *E6) {
	n := len(vector)
	if len(layer) != 2*n || len(halfInvTwiddles) != n {
		panic("vectorE6.FoldPairs: len(layer) must be 2·len(vector) and len(halfInvTwiddles) len(vector)")
	}
	if n == 0 {
		return
	}
	aa := *alpha
	const blockSize = 16
	if cpu.SupportAVX512 && n >= blockSize {
		nr := n - n%blockSize
		K := scalarMulE6Matrix(&aa)
		vectorFoldPairs_E6_avx512(&vector[0], &layer[0], &halfInvTwiddles[0], &K[0], uint64(nr))
		vector, layer, halfInvTwiddles = vector[nr:], layer[2*nr:], halfInvTwiddles[nr:]
	}
	foldPairsE6Generic(vector, layer, halfInvTwiddles, &aa)
}

func foldPairsE6Generic(vector, layer VectorE6, halfInvTwiddles fr.Vector, alpha *E6) {
	var s, d E6
	for j := range vector {
		p, q := &layer[2*j], &layer[2*j+1]
		s.Add(p, q)
		s.Halve()
		d.Sub(p, q)
		d.MulByElement(&d, &halfInvTwiddles[j])
		d.Mul(&d, alpha)
		vector[j].Add(&s, &d)
	}
}

// InnerProductByElement returns the sum of vector[i] * a[i], where a[i] ∈ F_p.
func (vector VectorE6) InnerProductByElement(a fr.Vector) E6 {
	if len(vector) != len(a) {
		panic("vector.InnerProductByElement: vectors don't have the same length")
	}
	var res, tmp E6
	const blockSize = 8
	N := len(vector)
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		// t[16g + 8h + j] is a partial (unreduced) sum of lane 16g + 2j + h of
		// the 48-lane window, i.e. of coordinate (16g + 2j + h) % 6; reduce each
		// lane mod q before folding so the fold cannot overflow.
		var t [48]uint64
		vectorInnerProductByElement_E6_avx512(&t, &vector[0], &a[0], uint64(nr))
		var c [6]uint64
		for g := range 3 {
			for h := range 2 {
				for j := range 8 {
					c[(16*g+2*j+h)%6] += t[16*g+8*h+j] % q
				}
			}
		}
		res.B0.A0[0] = uint32(c[0] % q)
		res.B0.A1[0] = uint32(c[1] % q)
		res.B1.A0[0] = uint32(c[2] % q)
		res.B1.A1[0] = uint32(c[3] % q)
		res.B2.A0[0] = uint32(c[4] % q)
		res.B2.A1[0] = uint32(c[5] % q)
		vector, a = vector[nr:], a[nr:]
	}
	for i := range vector {
		tmp.MulByElement(&vector[i], &a[i])
		res.Add(&res, &tmp)
	}
	return res
}

// Butterfly computes the in-place butterfly operation on two vectors of E6 elements.
// If other overlaps with vector, the result is undefined; the caller should use a temp vector.
func (vector VectorE6) Butterfly(other VectorE6) {
	N := len(vector)
	if len(other) != N {
		panic("vectorE6.Butterfly: vectors don't have the same length")
	}
	// Butterfly is fully componentwise on fr.Element: every fr lane in vector is
	// added/subtracted with its counterpart in other. The existing E4 kernel
	// performs that exact pattern on 64-byte (= 16 fr) chunks; reinterpret the
	// pair as a (3/2 N)-length E4 array and reuse it. Requires N % 8 == 0 so
	// 6N/4 is a multiple of the kernel's 4-E4 inner block.
	const blockSize = 8
	if !cpu.SupportAVX512 || N < blockSize {
		for i := range N {
			ButterflyE6(&vector[i], &other[i])
		}
		return
	}
	r := N % blockSize
	nr := uint64(N - r)
	vectorButterfly_avx512(
		(*E4)(unsafe.Pointer(&vector[0])),
		(*E4)(unsafe.Pointer(&other[0])),
		nr*3/2,
	)
	for i := N - r; i < N; i++ {
		ButterflyE6(&vector[i], &other[i])
	}
}

// ButterflyPair computes the in-place butterfly operation of each pair in the vector,
// i.e. vector[0], vector[1]; vector[2], vector[3]; ...
func (vector VectorE6) ButterflyPair() {
	N := len(vector)
	if N%2 != 0 {
		panic("vectorE6.ButterflyPair: vector length must be even")
	}
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := uint64(N - r)
		vectorButterflyPair_E6_avx512(&vector[0], nr)
		for i := N - r; i < N; i += 2 {
			a, b := &vector[i], &vector[i+1]

			fr.Butterfly(&a.B0.A0, &b.B0.A0)
			fr.Butterfly(&a.B0.A1, &b.B0.A1)
			fr.Butterfly(&a.B1.A0, &b.B1.A0)
			fr.Butterfly(&a.B1.A1, &b.B1.A1)
			fr.Butterfly(&a.B2.A0, &b.B2.A0)
			fr.Butterfly(&a.B2.A1, &b.B2.A1)

		}
		return
	}
	// Hand-inlined: ButterflyE6 alone is 96 instructions which exceeds the
	// inliner's budget, so the call wasn't being inlined into the hot loop.
	for i := 0; i < N; i += 2 {
		a, b := &vector[i], &vector[i+1]

		fr.Butterfly(&a.B0.A0, &b.B0.A0)
		fr.Butterfly(&a.B0.A1, &b.B0.A1)
		fr.Butterfly(&a.B1.A0, &b.B1.A0)
		fr.Butterfly(&a.B1.A1, &b.B1.A1)
		fr.Butterfly(&a.B2.A0, &b.B2.A0)
		fr.Butterfly(&a.B2.A1, &b.B2.A1)

	}
}

// MulByElementThenButterfly multiplies each element of other by the corresponding
// scalar in twiddles, then applies the in-place butterfly between vector and other.
func (vector VectorE6) MulByElementThenButterfly(other VectorE6, twiddles fr.Vector) {
	N := len(vector)
	if len(other) != N || len(twiddles) != N {
		panic("vectorE6.MulByElementThenButterfly: vectors don't have the same length")
	}
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := uint64(N - r)
		vectorDITWithTwiddles_E6_avx512(&vector[0], &other[0], &twiddles[0], nr)
		for i := N - r; i < N; i++ {
			other[i].MulByElement(&other[i], &twiddles[i])
			ButterflyE6(&vector[i], &other[i])
		}
		return
	}
	for i := range N {
		other[i].MulByElement(&other[i], &twiddles[i])
		ButterflyE6(&vector[i], &other[i])
	}
}

// ButterflyThenMulByElement applies the in-place butterfly between vector and
// other, then multiplies each element of other by the corresponding scalar in twiddles.
func (vector VectorE6) ButterflyThenMulByElement(other VectorE6, twiddles fr.Vector) {
	N := len(vector)
	if len(other) != N || len(twiddles) != N {
		panic("vectorE6.ButterflyThenMulByElement: vectors don't have the same length")
	}
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := uint64(N - r)
		vectorDIFWithTwiddles_E6_avx512(&vector[0], &other[0], &twiddles[0], nr)
		for i := N - r; i < N; i++ {
			ButterflyE6(&vector[i], &other[i])
			other[i].MulByElement(&other[i], &twiddles[i])
		}
		return
	}
	for i := range N {
		ButterflyE6(&vector[i], &other[i])
		other[i].MulByElement(&other[i], &twiddles[i])
	}
}

// MulByElement multiplies each element of a by the corresponding scalar in b and
// stores the result in vector.
func (vector VectorE6) MulByElement(a VectorE6, b fr.Vector) {
	N := len(vector)
	if len(a) != N || len(b) != N {
		panic("vectorE6.MulByElement: vectors don't have the same length")
	}
	const blockSize = 8
	if !cpu.SupportAVX512 || N < blockSize {
		for i := range N {
			vector[i].MulByElement(&a[i], &b[i])
		}
		return
	}
	r := N % blockSize
	nr := uint64(N - r)
	vectorMulByElement_E6_avx512(&vector[0], &a[0], &b[0], nr)
	for i := N - r; i < N; i++ {
		vector[i].MulByElement(&a[i], &b[i])
	}
}

// MulAccByElement accumulates a[i]*b[i] into each element of vector:
// vector[i] += a[i] * b[i], where b[i] is a base field scalar.
func (vector VectorE6) MulAccByElement(a VectorE6, b fr.Vector) {
	N := len(vector)
	if len(a) != N || len(b) != N {
		panic("vectorE6.MulAccByElement: vectors don't have the same length")
	}
	const blockSize = 8
	if !cpu.SupportAVX512 || N < blockSize {
		mulAccByElementE6Generic(vector, a, b)
		return
	}
	r := N % blockSize
	nr := uint64(N - r)
	vectorMulAccByElement_E6_avx512(&vector[0], &a[0], &b[0], nr)
	mulAccByElementE6Generic(vector[N-r:], a[N-r:], b[N-r:])
}

func mulAccByElementE6Generic(vector, a VectorE6, b fr.Vector) {
	var tmp E6
	for i := range vector {
		tmp.MulByElement(&a[i], &b[i])
		vector[i].Add(&vector[i], &tmp)
	}
}

// ScalarMulByElement multiplies each element of a by the same fr element b and
// stores the result in vector.
func (vector VectorE6) ScalarMulByElement(a VectorE6, b *fr.Element) {
	if len(a) != len(vector) {
		panic("vectorE6.ScalarMulByElement: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}

	// E6 is laid out as 6 contiguous fr.Element; cast and reuse the optimized
	// fr.Vector.ScalarMul.
	M := len(a) * 6
	vBase := fr.Vector(unsafe.Slice((*fr.Element)(unsafe.Pointer(&a[0])), M))
	vRes := fr.Vector(unsafe.Slice((*fr.Element)(unsafe.Pointer(&vector[0])), M))
	vRes.ScalarMul(vBase, b)
}

// ScalarMulAccByElement sets vector[i] += a[i] * s for all i, where a is a
// base-field vector and s an E6 scalar.
//
// It is equivalent to vector.ScalarMulAccBase(a, s).
func (vector VectorE6) ScalarMulAccByElement(a fr.Vector, s *E6) {
	vector.ScalarMulAccBase(a, s)
}

// ScalarMulAccBase sets vector[i] += a[i] * c for all i, where a is a
// base-field vector and c an extension scalar.
//
// c may point into vector.
func (vector VectorE6) ScalarMulAccBase(a fr.Vector, c *E6) {
	N := len(vector)
	if len(a) != N {
		panic("vectorE6.ScalarMulAccBase: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	cc := *c
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		sTiled := tileE6Scalar(&cc)
		vectorScalarMulAccByElement_E6_avx512(&vector[0], &a[0], &sTiled[0], uint64(nr))
		vector, a = vector[nr:], a[nr:]
	}
	scalarMulAccByElementE6Generic(vector, a, &cc)
}

func scalarMulAccByElementE6Generic(vector VectorE6, a fr.Vector, s *E6) {
	var tmp E6
	for i := range vector {
		tmp.MulByElement(s, &a[i])
		vector[i].Add(&vector[i], &tmp)
	}
}

// MulAcc sets vector[i] += a[i] * b[i] for all i.
//
// vector may be identical to a and/or b; partially overlapping slices are not
// supported.
func (vector VectorE6) MulAcc(a, b VectorE6) {
	N := len(vector)
	if len(a) != N || len(b) != N {
		panic("vectorE6.MulAcc: vectors don't have the same length")
	}
	const blockSize = 16
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		vectorMulAcc_E6_avx512(&vector[0], &a[0], &b[0], uint64(nr))
		vector, a, b = vector[nr:], a[nr:], b[nr:]
	}
	var t E6
	for i := range vector {
		t.Mul(&a[i], &b[i])
		vector[i].Add(&vector[i], &t)
	}
}

// ScalarMulBase sets vector[i] = a[i] * c for all i, where a is a base-field
// vector and c an extension scalar.
//
// c may point into vector.
func (vector VectorE6) ScalarMulBase(a fr.Vector, c *E6) {
	N := len(vector)
	if len(a) != N {
		panic("vectorE6.ScalarMulBase: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	cc := *c
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		sTiled := tileE6Scalar(&cc)
		vectorScalarMulBase_E6_avx512(&vector[0], &a[0], &sTiled[0], uint64(nr))
		vector, a = vector[nr:], a[nr:]
	}
	for i := range vector {
		vector[i].MulByElement(&cc, &a[i])
	}
}

// ScalarMulAdd sets vector[i] = vector[i] * c + b[i] for all i: one Horner step
// applied across the vector.
//
// vector may be identical to b, and c may point into vector or b; partially
// overlapping slices are not supported.
func (vector VectorE6) ScalarMulAdd(b VectorE6, c *E6) {
	N := len(vector)
	if len(b) != N {
		panic("vectorE6.ScalarMulAdd: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	cc := *c
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		Kcol := e6ScalarMulKcol(&cc)
		vectorScalarMulAdd_E6_avx512(&vector[0], &b[0], &Kcol[0], uint64(nr))
		vector, b = vector[nr:], b[nr:]
	}
	// compute into t first: b may alias vector.
	var t E6
	for i := range vector {
		t.Mul(&vector[i], &cc)
		vector[i].Add(&t, &b[i])
	}
}

// ScalarMulAddBase sets vector[i] = vector[i] * c + b[i] for all i, where b is
// a base-field vector: one Horner step applied across the vector.
//
// To compute a random linear combination ∑ cᵏ·colₖ of base-field columns
// whose powers of c are known, prefer ScalarMulAccBase with each power: it
// costs one extension-by-base product per element, whereas this method costs
// a full extension product. Use ScalarMulAddBase for streaming Horner
// evaluation when the powers of c are not precomputed.
//
// c may point into vector.
func (vector VectorE6) ScalarMulAddBase(b fr.Vector, c *E6) {
	N := len(vector)
	if len(b) != N {
		panic("vectorE6.ScalarMulAddBase: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	cc := *c
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		Kcol := e6ScalarMulKcol(&cc)
		vectorScalarMulAddBase_E6_avx512(&vector[0], &b[0], &Kcol[0], uint64(nr))
		vector, b = vector[nr:], b[nr:]
	}
	for i := range vector {
		vector[i].Mul(&vector[i], &cc)
		vector[i].B0.A0.Add(&vector[i].B0.A0, &b[i])
	}
}

// ScalarMulAcc accumulates vector[i] += a[i] * s, where s is a fixed E6 scalar.
// vector may be identical to a, and s may point into vector or a.
func (vector VectorE6) ScalarMulAcc(a VectorE6, s *E6) {
	N := len(vector)
	if len(a) != N {
		panic("vectorE6.ScalarMulAcc: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	// copy s: it may point into vector, which the loop overwrites.
	ss := *s
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		Kcol := e6ScalarMulKcol(&ss)
		vectorScalarMulAcc_E6_avx512(&vector[0], &a[0], &Kcol[0], uint64(nr))
		vector, a = vector[nr:], a[nr:]
	}
	scalarMulAccE6Generic(vector, a, &ss)
}

func scalarMulAccE6Generic(vector, a VectorE6, s *E6) {
	var tmp E6
	for i := range vector {
		tmp.Mul(&a[i], s)
		vector[i].Add(&vector[i], &tmp)
	}
}

// ScalarMul sets vector[i] = a[i] * s, where s is a fixed E6 scalar.
// vector may be identical to a, and s may point into vector or a.
func (vector VectorE6) ScalarMul(a VectorE6, s *E6) {
	N := len(vector)
	if len(a) != N {
		panic("vectorE6.ScalarMul: vectors don't have the same length")
	}
	if len(vector) == 0 {
		return
	}
	// copy s: it may point into vector, which the loop overwrites.
	ss := *s
	const blockSize = 8
	if cpu.SupportAVX512 && N >= blockSize {
		r := N % blockSize
		nr := N - r
		Kcol := e6ScalarMulKcol(&ss)
		vectorScalarMul_E6_avx512(&vector[0], &a[0], &Kcol[0], uint64(nr))
		vector, a = vector[nr:], a[nr:]
	}
	scalarMulE6Generic(vector, a, &ss)
}

func scalarMulE6Generic(vector, a VectorE6, s *E6) {
	for i := range vector {
		vector[i].Mul(&a[i], s)
	}
}

// tileE6Scalar tiles the six fr coordinates of s across 48 lanes (period 6, the
// 8-E6 = 3-zmm broadcast window consumed by vectorScalarMulAccByElement_E6_avx512,
// vectorScalarAdd_E6_avx512 and vectorScalarSubFrom_E6_avx512).
func tileE6Scalar(s *E6) [48]fr.Element {
	c := [6]fr.Element{s.B0.A0, s.B0.A1, s.B1.A0, s.B1.A1, s.B2.A0, s.B2.A1}
	var out [48]fr.Element
	for p := range out {
		out[p] = c[p%6]
	}
	return out
}

// scalarMulE6Matrix builds the 6×6 constant matrix K (row-major) such that, for
// a fixed E6 scalar s, the map a ↦ a·s is c = K·a over the six fr coordinates.
// It mirrors E6.Mul(a, s) exactly, so the AVX-512 kernels stay bit-identical to
// the scalar path. Coordinate order is (B0.A0, B0.A1, B1.A0, B1.A1, B2.A0, B2.A1)
// with the tower E6 = E2[v]/(v³-(u+1)), E2 = Fr[u]/(u²-α), α = 3.
func scalarMulE6Matrix(s *E6) [36]fr.Element {
	b0, b1, b2, b3, b4, b5 := s.B0.A0, s.B0.A1, s.B1.A0, s.B1.A1, s.B2.A0, s.B2.A1

	mul3 := func(x *fr.Element) fr.Element {
		var r fr.Element
		r.Add(x, x).Add(&r, x)
		return r
	}
	add := func(x, y *fr.Element) fr.Element {
		var r fr.Element
		r.Add(x, y)
		return r
	}

	m1, m2, m3, m4, m5 := mul3(&b1), mul3(&b2), mul3(&b3), mul3(&b4), mul3(&b5)
	m23 := add(&m2, &m3)    // 3b2 + 3b3
	m45 := add(&m4, &m5)    // 3b4 + 3b5
	b45 := add(&b4, &b5)    // b4 + b5
	b23 := add(&b2, &b3)    // b2 + b3
	b4_3b5 := add(&b4, &m5) // b4 + 3b5
	b2_3b3 := add(&b2, &m3) // b2 + 3b3

	return [36]fr.Element{
		b0, m1, b4_3b5, m45, b2_3b3, m23,
		b1, b0, b45, b4_3b5, b23, b2_3b3,
		b2, m3, b0, m1, b4_3b5, m45,
		b3, b2, b1, b0, b45, b4_3b5,
		b4, m5, b2, m3, b0, m1,
		b5, b4, b3, b2, b1, b0,
	}
}

// e6ScalarMulKcol builds the tiled K columns consumed by the AVX-512
// vectorScalarMul(Acc)_E6_avx512 kernels: for source coordinate i, K's column i
// is tiled across the 48-lane (8-E6 = 3-zmm) window with period 6, so
// out[i*48 + p] = K[p%6][i]. See scalarMulE6Matrix for the layout of K.
func e6ScalarMulKcol(s *E6) [6 * 48]fr.Element {
	K := scalarMulE6Matrix(s)
	var out [6 * 48]fr.Element
	for i := range 6 {
		for p := range 48 {
			out[i*48+p] = K[(p%6)*6+i]
		}
	}
	return out
}
